// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import java.util.List;

import org.junit.jupiter.api.Test;

/**
 * Unit spec for startup cost and slice awareness.
 * <p>
 * Total work alone cannot choose correctly under a small LIMIT. A strategy that is cheapest overall can be the worst
 * possible choice when the consumer wants three rows, because all of its cost is front-loaded — a parallel group
 * creates worker threads, snapshot sources and read transactions before row one, and a hash join sweeps its entire
 * build side. Separating the front-loaded part from the streaming remainder is what lets the arbiter answer "what will
 * this actually cost me for the rows I am going to ask for".
 * <p>
 * Before this, the engine's only notion of the same idea was {@code isShortFiniteSlice} — a hardcoded 256-row threshold
 * in one static method, consulted by two rungs and ignored by the hash join, which is the worst offender.
 */
public class LmdbNativeStartupCostTest {

	/** Same reason as {@link LmdbNativeStrategyArbiterTest}: these pin the rule, not the learned behaviour. */
	@org.junit.jupiter.api.BeforeEach
	public void isolateFromLearnedCalibration() {
		LmdbNativeCostCalibration.reset();
	}

	private static LmdbNativeStrategyProposal<String> proposal(String tag, double totalWork, double startupWork,
			double rows) {
		return new LmdbNativeStrategyProposal<>(() -> tag, LmdbNativeWork.exact(totalWork),
				LmdbNativeWork.exact(startupWork), rows, tag, () -> {
				});
	}

	@Test
	public void withoutASliceEffectiveWorkIsTotalWork() {
		LmdbNativeStrategyProposal<String> parallel = proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES,
				300_000D, 250_000D, 1_000_000D);

		assertThat(parallel.effectiveWork(-1D))
				.as("an unbounded consumer pays the whole cost, so nothing is prorated")
				.isEqualTo(parallel.work);
	}

	@Test
	public void aSliceLargerThanTheResultChangesNothing() {
		LmdbNativeStrategyProposal<String> plan = proposal("batch", 1_000D, 0D, 100D);

		assertThat(plan.effectiveWork(500D))
				.as("asking for more rows than exist is the same as asking for all of them")
				.isEqualTo(plan.work);
	}

	@Test
	public void frontLoadedWorkIsPaidInFullEvenForOneRow() {
		LmdbNativeStrategyProposal<String> parallel = proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES,
				300_000D, 250_000D, 1_000_000D);

		double oneRow = parallel.effectiveWork(1D).high();

		assertThat(oneRow)
				.as("worker startup happens whether the consumer takes one row or a million")
				.isGreaterThanOrEqualTo(250_000D);
		assertThat(oneRow)
				.as("but the streaming remainder is prorated, so it is not the full total either")
				.isLessThan(300_000D);
	}

	@Test
	public void aStreamingStrategyIsProratedAlmostEntirelyAway() {
		LmdbNativeStrategyProposal<String> streaming = proposal("nestedLoop", 1_000_000D, 0D, 1_000_000D);

		assertThat(streaming.effectiveWork(1D).high())
				.as("with no startup cost, taking one row of a million costs about one row of work")
				.isCloseTo(1D, within(0.001d));
	}

	@Test
	public void aSmallLimitPicksStreamingOverACheaperButFrontLoadedStrategy() {
		// Parallel is cheaper overall -- 300k against 1M -- and would win on total work.
		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 300_000D, 250_000D, 1_000_000D),
				proposal(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP, 1_000_000D, 0D, 1_000_000D));

		assertThat(candidates.get(LmdbNativeStrategyArbiter.rank(candidates, -1D)).tag)
				.as("unbounded, the cheaper total wins")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES);

		assertThat(candidates.get(LmdbNativeStrategyArbiter.rank(candidates, 5D)).tag)
				.as("for five rows, paying 250k of worker startup to save streaming cost is the wrong trade")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
	}

	@Test
	public void aLargeLimitStillPicksTheCheaperTotal() {
		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 300_000D, 250_000D, 1_000_000D),
				proposal(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP, 1_000_000D, 0D, 1_000_000D));

		assertThat(candidates.get(LmdbNativeStrategyArbiter.rank(candidates, 900_000D)).tag)
				.as("once the consumer wants most of the result, the startup amortizes and parallel wins again")
				.isEqualTo(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES);
	}

	@Test
	public void anUnknownRowCountDeclinesToProrate() {
		LmdbNativeStrategyProposal<String> unknownRows = proposal("batch", 1_000D, 500D, Double.NaN);

		assertThat(unknownRows.effectiveWork(1D))
				.as("without knowing how many rows exist, the fraction consumed is unknowable; the model must "
						+ "decline to guess rather than invent a discount")
				.isEqualTo(unknownRows.work);
	}

	@Test
	public void proposalsWithoutAStartupCostKeepTodaysBehaviour() {
		// Every existing call site uses a constructor that defaults startupWork to ZERO and rows to NaN, so this
		// milestone must be inert for them.
		LmdbNativeStrategyProposal<String> legacy = new LmdbNativeStrategyProposal<>(() -> "batch", 1_000D,
				LmdbNativeAttemptMetrics.PATH_BATCH);

		assertThat(legacy.startupWork).isEqualTo(LmdbNativeWork.ZERO);
		assertThat(legacy.estRows).isNaN();
		assertThat(legacy.effectiveWork(1D)).isEqualTo(legacy.work);
	}
}
